        "c": "int trap(int* height, int heightSize) {\n    int left = 0, right = heightSize - 1;\n    int preMax = 0, sufMax = 0, ans = 0;\n    while (left < right) {\n        if (height[left] > preMax) preMax = height[left];\n        if (height[right] > sufMax) sufMax = height[right];\n        if (preMax < sufMax) {\n            ans += preMax - height[left];\n            left++;\n        } else {\n            ans += sufMax - height[right];\n            right--;\n        }\n    }\n    return ans;\n}"
