        "python": "from collections import defaultdict\n\nclass Solution:\n    def minWindow(self, s: str, t: str) -> str:\n        if len(s) < len(t):\n            return \"\"\n        need = defaultdict(int)\n        for ch in t:\n            need[ch] += 1\n        # less 记录还有多少“种”字符尚未凑够数量\n        less = len(need)\n\n        win = defaultdict(int)\n        ans_left, ans_right = -1, len(s)\n        left = 0\n        for right, ch in enumerate(s):\n            win[ch] += 1\n            if win[ch] == need[ch]:\n                less -= 1\n            # 所有字符种类均已达标，尝试收缩左边界求最短窗口\n            while less == 0:\n                if right - left < ans_right - ans_left:\n                    ans_left, ans_right = left, right\n                out_ch = s[left]\n                if win[out_ch] == need[out_ch]:\n                    less += 1\n                win[out_ch] -= 1\n                left += 1\n        return \"\" if ans_left < 0 else s[ans_left : ans_right + 1]",
        "cpp": "#include <string>\nusing namespace std;\n\nclass Solution {\npublic:\n    string minWindow(string s, string t) {\n        if (s.size() < t.size()) return \"\";\n        int need[128] = {0}, win[128] = {0};\n        int less = 0; // 还差多少种字符未达标\n        for (unsigned char ch : t) {\n            if (need[ch] == 0) less++;\n            need[ch]++;\n        }\n\n        int ansLeft = -1, minLen = (int)s.size() + 1;\n        int left = 0;\n        for (int right = 0; right < (int)s.size(); ++right) {\n            unsigned char ch = s[right];\n            win[ch]++;\n            if (win[ch] == need[ch]) {\n                less--;\n            }\n            while (less == 0) {\n                if (right - left + 1 < minLen) {\n                    minLen = right - left + 1;\n                    ansLeft = left;\n                }\n                unsigned char outCh = s[left];\n                if (win[outCh] == need[outCh]) {\n                    less++;\n                }\n                win[outCh]--;\n                left++;\n            }\n        }\n        return ansLeft < 0 ? \"\" : s.substr(ansLeft, minLen);\n    }\n};",
        "java": "class Solution {\n    public String minWindow(String s, String t) {\n        int m = s.length(), n = t.length();\n        if (m < n) return \"\";\n        int[] need = new int[128];\n        int[] win = new int[128];\n        int less = 0;\n        for (int i = 0; i < n; i++) {\n            char ch = t.charAt(i);\n            if (need[ch] == 0) less++;\n            need[ch]++;\n        }\n\n        int ansLeft = -1, minLen = m + 1;\n        int left = 0;\n        for (int right = 0; right < m; right++) {\n            char ch = s.charAt(right);\n            win[ch]++;\n            if (win[ch] == need[ch]) {\n                less--;\n            }\n            while (less == 0) {\n                if (right - left + 1 < minLen) {\n                    minLen = right - left + 1;\n                    ansLeft = left;\n                }\n                char outCh = s.charAt(left);\n                if (win[outCh] == need[outCh]) {\n                    less++;\n                }\n                win[outCh]--;\n                left++;\n            }\n        }\n        return ansLeft < 0 ? \"\" : s.substring(ansLeft, ansLeft + minLen);\n    }\n}",
        "c": "#include <stdlib.h>\n#include <string.h>\n\nchar* minWindow(char* s, char* t) {\n    int m = (int)strlen(s), n = (int)strlen(t);\n    if (m < n) {\n        char* empty = (char*)calloc(1, sizeof(char));\n        return empty;\n    }\n\n    int need[128] = {0}, win[128] = {0};\n    int less = 0;\n    for (int i = 0; i < n; i++) {\n        unsigned char ch = (unsigned char)t[i];\n        if (need[ch] == 0) less++;\n        need[ch]++;\n    }\n\n    int ansLeft = -1, minLen = m + 1;\n    int left = 0;\n    for (int right = 0; right < m; right++) {\n        unsigned char ch = (unsigned char)s[right];\n        win[ch]++;\n        if (win[ch] == need[ch]) {\n            less--;\n        }\n        while (less == 0) {\n            if (right - left + 1 < minLen) {\n                minLen = right - left + 1;\n                ansLeft = left;\n            }\n            unsigned char outCh = (unsigned char)s[left];\n            if (win[outCh] == need[outCh]) {\n                less++;\n            }\n            win[outCh]--;\n            left++;\n        }\n    }\n\n    if (ansLeft < 0) {\n        return (char*)calloc(1, sizeof(char));\n    }\n    char* res = (char*)malloc((minLen + 1) * sizeof(char));\n    memcpy(res, s + ansLeft, minLen);\n    res[minLen] = '\\0';\n    return res;\n}"
