        "python": "from typing import List\n\nclass Solution:\n    def maxSubArray(self, nums: List[int]) -> int:\n        # Kadane 算法：cur 表示以当前元素结尾的最大子数组和\n        cur = 0\n        ans = nums[0]  # 切勿初始化为 0，需兼容全负数数组\n        for x in nums:\n            # 若前面的累加和 cur < 0，对当前元素是负累，直接丢弃另起炉灶\n            cur = x if cur < 0 else cur + x\n            if cur > ans:\n                ans = cur\n        return ans",
