        "python": "class Solution:\n    def removeNthFromEnd(self, head: Optional[ListNode], n: int) -> Optional[ListNode]:\n        # 必建 dummy 节点，应对删除原头节点（倒数第 L 个节点）的边界情况\n        dummy = ListNode(0, head)\n        slow = fast = dummy\n        # 快指针先向前走 n 步，拉开固定间距 n\n        for _ in range(n):\n            fast = fast.next\n        # 两指针同步前进，当 fast 到达尾节点时，slow 恰好停在待删节点的前驱\n        while fast.next:\n            slow = slow.next\n            fast = fast.next\n        slow.next = slow.next.next\n        return dummy.next",
        "cpp": "class Solution {\npublic:\n    ListNode* removeNthFromEnd(ListNode* head, int n) {\n        ListNode dummy(0, head);\n        ListNode *slow = &dummy, *fast = &dummy;\n        for (int i = 0; i < n; ++i) {\n            fast = fast->next;\n        }\n        while (fast->next != nullptr) {\n            slow = slow->next;\n            fast = fast->next;\n        }\n        // 摘除目标节点并释放其堆内存（良好 C++ 工程习惯）\n        ListNode* toDelete = slow->next;\n        slow->next = toDelete->next;\n        delete toDelete;\n        return dummy.next;\n    }\n};",
        "java": "class Solution {\n    public ListNode removeNthFromEnd(ListNode head, int n) {\n        ListNode dummy = new ListNode(0, head);\n        ListNode slow = dummy, fast = dummy;\n        for (int i = 0; i < n; i++) {\n            fast = fast.next;\n        }\n        while (fast.next != null) {\n            slow = slow.next;\n            fast = fast.next;\n        }\n        // 跨过待删节点，脱离引用的节点将由 GC 自动回收\n        slow.next = slow.next.next;\n        return dummy.next;\n    }\n}",
        "c": "struct ListNode* removeNthFromEnd(struct ListNode* head, int n) {\n    struct ListNode dummy = {0, head};\n    struct ListNode *slow = &dummy, *fast = &dummy;\n    for (int i = 0; i < n; i++) {\n        fast = fast->next;\n    }\n    while (fast->next != NULL) {\n        slow = slow->next;\n        fast = fast->next;\n    }\n    struct ListNode* toDelete = slow->next;\n    slow->next = toDelete->next;\n    free(toDelete);\n    return dummy.next;\n}"
