        "python": "class Solution:\n    def kthSmallest(self, root: Optional[TreeNode], k: int) -> int:\n        ans = 0\n\n        def inorder(node: Optional[TreeNode]) -> None:\n            nonlocal k, ans\n            if not node or k == 0:\n                return\n            inorder(node.left)\n            if k == 0:\n                return\n            # 中序时机：每访问一个节点 k 减 1，减到 0 即命中第 k 小元素\n            k -= 1\n            if k == 0:\n                ans = node.val\n                return\n            inorder(node.right)\n\n        inorder(root)\n        return ans",
