        "c": "static void inorder(struct TreeNode* node, int* k, int* ans) {\n    if (node == NULL || *k == 0) return;\n    inorder(node->left, k, ans);\n    if (*k == 0) return;\n    if (--(*k) == 0) {\n        *ans = node->val;\n        return;\n    }\n    inorder(node->right, k, ans);\n}\n\nint kthSmallest(struct TreeNode* root, int k) {\n    int ans = 0;\n    inorder(root, &k, &ans);\n    return ans;\n}"
