        "python": "from math import inf\n\nclass Solution:\n    def maxPathSum(self, root: Optional[TreeNode]) -> int:\n        # 坑点防御：节点值可全为负，全局初值必须设为 -inf 而非 0！\n        ans = -inf\n\n        def dfs(node: Optional[TreeNode]) -> int:\n            nonlocal ans\n            if not node:\n                return 0\n            # 子树贡献若为负数只会拖累路径和，直接与 0 取 max 舍弃不要\n            left_gain = max(0, dfs(node.left))\n            right_gain = max(0, dfs(node.right))\n            # 1. 以当前节点为最高拐点，左右双链拼合尝试刷新全局最大路径和\n            ans = max(ans, node.val + left_gain + right_gain)\n            # 2. 向上汇报给父节点时禁止分叉，只能挑选贡献较大的一侧单链延伸\n            return node.val + max(left_gain, right_gain)\n\n        dfs(root)\n        return ans",
        "cpp": "#include <climits>\n\nclass Solution {\n    int ans = INT_MIN;\n\n    int dfs(TreeNode* node) {\n        if (node == nullptr) return 0;\n        int L = max(0, dfs(node->left));\n        int R = max(0, dfs(node->right));\n        ans = max(ans, node->val + L + R);\n        return node->val + max(L, R);\n    }\n\npublic:\n    int maxPathSum(TreeNode* root) {\n        ans = INT_MIN;\n        dfs(root);\n        return ans;\n    }\n};",
        "java": "class Solution {\n    private int ans;\n\n    public int maxPathSum(TreeNode root) {\n        ans = Integer.MIN_VALUE;\n        dfs(root);\n        return ans;\n    }\n\n    private int dfs(TreeNode node) {\n        if (node == null) return 0;\n        int L = Math.max(0, dfs(node.left));\n        int R = Math.max(0, dfs(node.right));\n        ans = Math.max(ans, node.val + L + R);\n        return node.val + Math.max(L, R);\n    }\n}",
