      "isTop20": false,
      "codes": {
        "python": "class TrieNode:\n    __slots__ = ('children', 'is_end')\n\n    def __init__(self):\n        self.children = {}\n        self.is_end = False\n\n\nclass Trie:\n    def __init__(self):\n        self.root = TrieNode()\n\n    def insert(self, word: str) -> None:\n        node = self.root\n        for ch in word:\n            if ch not in node.children:\n                node.children[ch] = TrieNode()\n            node = node.children[ch]\n        node.is_end = True\n\n    def _search_prefix(self, prefix: str) -> Optional[TrieNode]:\n        # 公共辅助函数：沿前缀字符向下走，中途断路返回 None，否则返回终点节点\n        node = self.root\n        for ch in prefix:\n            if ch not in node.children:\n                return None\n            node = node.children[ch]\n        return node\n\n    def search(self, word: str) -> bool:\n        node = self._search_prefix(word)\n        return node is not None and node.is_end\n\n    def startsWith(self, prefix: str) -> bool:\n        return self._search_prefix(prefix) is not None",
        "cpp": "class Trie {\n    Trie* children[26]{};  // 值初始化自动将全部 26 个指针置为 nullptr\n    bool isEnd = false;\n\n    const Trie* searchPrefix(const string& prefix) const {\n        const Trie* node = this;\n        for (char ch : prefix) {\n            int idx = ch - 'a';\n            if (node->children[idx] == nullptr) {\n                return nullptr;\n            }\n            node = node->children[idx];\n        }\n        return node;\n    }\n\npublic:\n    Trie() = default;\n\n    void insert(string word) {\n        Trie* node = this;\n        for (char ch : word) {\n            int idx = ch - 'a';\n            if (node->children[idx] == nullptr) {\n                node->children[idx] = new Trie();\n            }\n            node = node->children[idx];\n        }\n        node->isEnd = true;\n    }\n\n    bool search(string word) {\n        const Trie* node = searchPrefix(word);\n        return node != nullptr && node->isEnd;\n    }\n\n    bool startsWith(string prefix) {\n        return searchPrefix(prefix) != nullptr;\n    }\n};",
        "java": "class Trie {\n    private final Trie[] children = new Trie[26];\n    private boolean isEnd = false;\n\n    public Trie() {}\n\n    public void insert(String word) {\n        Trie node = this;\n        for (int i = 0; i < word.length(); i++) {\n            int idx = word.charAt(i) - 'a';\n            if (node.children[idx] == null) {\n                node.children[idx] = new Trie();\n            }\n            node = node.children[idx];\n        }\n        node.isEnd = true;\n    }\n\n    private Trie searchPrefix(String prefix) {\n        Trie node = this;\n        for (int i = 0; i < prefix.length(); i++) {\n            int idx = prefix.charAt(i) - 'a';\n            if (node.children[idx] == null) {\n                return null;\n            }\n            node = node.children[idx];\n        }\n        return node;\n    }\n\n    public boolean search(String word) {\n        Trie node = searchPrefix(word);\n        return node != null && node.isEnd;\n    }\n\n    public boolean startsWith(String prefix) {\n        return searchPrefix(prefix) != null;\n    }\n}",
        "c": "typedef struct Trie {\n    struct Trie* children[26];\n    bool isEnd;\n} Trie;\n\nTrie* trieCreate() {\n    // calloc 自动将 26 个子指针清零为 NULL，isEnd 置为 false\n    return (Trie*)calloc(1, sizeof(Trie));\n}\n\nvoid trieInsert(Trie* obj, char* word) {\n    Trie* node = obj;\n    for (int i = 0; word[i] != '\\0'; i++) {\n        int idx = word[i] - 'a';\n        if (node->children[idx] == NULL) {\n            node->children[idx] = trieCreate();\n        }\n        node = node->children[idx];\n    }\n    node->isEnd = true;\n}\n\nstatic Trie* searchPrefix(Trie* obj, char* prefix) {\n    Trie* node = obj;\n    for (int i = 0; prefix[i] != '\\0'; i++) {\n        int idx = prefix[i] - 'a';\n        if (node->children[idx] == NULL) {\n            return NULL;\n        }\n        node = node->children[idx];\n    }\n    return node;\n}\n\nbool trieSearch(Trie* obj, char* word) {\n    Trie* node = searchPrefix(obj, word);\n    return node != NULL && node->isEnd;\n}\n\nbool trieStartsWith(Trie* obj, char* prefix) {\n    return searchPrefix(obj, prefix) != NULL;\n}\n\nvoid trieFree(Trie* obj) {\n    if (obj == NULL) return;\n    for (int i = 0; i < 26; i++) {\n        trieFree(obj->children[i]);\n    }\n    free(obj);\n}"
      },
      "langNotes": {
        "python": "为高频大量实例化的 `TrieNode` 声明 `__slots__ = ('children', 'is_end')` 可省去每个节点默认的实例属性字典 `__dict__`，内存占用立减一半且属性读取更快；用字典存子节点能按需分配内存并轻松扩展至任意 Unicode 字符集。",
        "cpp": "利用 C++11 类内成员值初始化语法 `Trie* children[26]{};` 必须带上空花括号 `{}`，否则局部/堆上裸指针数组会包含未初始化的野指针导致段错误！抽离 `searchPrefix` 让 `search` 和 `startsWith` 高度复用。",
        "java": "Java 对象成员数组 `new Trie[26]` 默认全为 `null`、布尔成员默认 `false`，甚至无需单独再写 `TrieNode` 内部类，直接让 `Trie` 类自身充当树节点即可。",
        "c": "分配节点务必优先用 `calloc(1, sizeof(Trie))` 而非 `malloc`，它能一步到位将 26 个指针置为 `NULL` 并把 `isEnd` 清零；销毁前缀树时必须按**后序遍历**顺序先递归释放所有孩子指针，最后再 `free(obj)`。"
      }
