        "c": "static int cmpInt(const void* a, const void* b) {\n    return (*(const int*)a > *(const int*)b) - (*(const int*)a < *(const int*)b);\n}\n\nstatic void dfs(const int* candidates, int n, int start, int remain,\n                int* path, int pathLen, int*** res, int* returnSize,\n                int** colSizes, int* cap) {\n    if (remain == 0) {\n        if (*returnSize == *cap) {\n            *cap *= 2;\n            *res = (int**)realloc(*res, (*cap) * sizeof(int*));\n            *colSizes = (int*)realloc(*colSizes, (*cap) * sizeof(int));\n        }\n        int* copy = (int*)malloc(pathLen * sizeof(int));\n        memcpy(copy, path, pathLen * sizeof(int));\n        (*colSizes)[*returnSize] = pathLen;\n        (*res)[(*returnSize)++] = copy;\n        return;\n    }\n    for (int i = start; i < n; i++) {\n        if (candidates[i] > remain) {\n            break;\n        }\n        path[pathLen] = candidates[i];\n        dfs(candidates, n, i, remain - candidates[i], path, pathLen + 1,\n            res, returnSize, colSizes, cap);\n    }\n}\n\nint** combinationSum(int* candidates, int candidatesSize, int target,\n                     int* returnSize, int** returnColumnSizes) {\n    qsort(candidates, candidatesSize, sizeof(int), cmpInt);\n    int cap = 160;  // 题目保证可行解少于 150 个，搭配 realloc 动态扩容万无一失\n    int** res = (int**)malloc(cap * sizeof(int*));\n    *returnColumnSizes = (int*)malloc(cap * sizeof(int));\n    *returnSize = 0;\n\n    int path[50];   // 最小元素 >= 2，target <= 40，递归最大深度不超过 20\n    dfs(candidates, candidatesSize, 0, target, path, 0,\n        &res, returnSize, returnColumnSizes, &cap);\n    return res;\n}"
