        "python": "class Solution:\n    def partition(self, s: str) -> List[List[str]]:\n        n = len(s)\n        # 1. 二维 DP 预处理任意子串 s[i..j] 是否为回文串\n        is_pal = [[False] * n for _ in range(n)]\n        for i in range(n - 1, -1, -1):  # i 必须倒序，保证 is_pal[i+1][j-1] 已算好\n            for j in range(i, n):\n                if s[i] == s[j] and (j - i <= 2 or is_pal[i + 1][j - 1]):\n                    is_pal[i][j] = True\n\n        res = []\n        path = []\n\n        # 2. 回溯枚举当前第一刀切在 end 位置\n        def dfs(start: int) -> None:\n            if start == n:\n                res.append(path[:])\n                return\n            for end in range(start, n):\n                if is_pal[start][end]:\n                    path.append(s[start:end + 1])\n                    dfs(end + 1)\n                    path.pop()\n\n        dfs(0)\n        return res",
        "cpp": "class Solution {\npublic:\n    vector<vector<string>> partition(string s) {\n        int n = s.size();\n        vector<vector<uint8_t>> isPal(n, vector<uint8_t>(n, 0));\n        for (int i = n - 1; i >= 0; --i) {\n            for (int j = i; j < n; ++j) {\n                if (s[i] == s[j] && (j - i <= 2 || isPal[i + 1][j - 1])) {\n                    isPal[i][j] = 1;\n                }\n            }\n        }\n\n        vector<vector<string>> res;\n        vector<string> path;\n\n        auto dfs = [&](auto&& self, int start) -> void {\n            if (start == n) {\n                res.push_back(path);\n                return;\n            }\n            for (int end = start; end < n; ++end) {\n                if (isPal[start][end]) {\n                    path.push_back(s.substr(start, end - start + 1));\n                    self(self, end + 1);\n                    path.pop_back();\n                }\n            }\n        };\n\n        dfs(dfs, 0);\n        return res;\n    }\n};",
        "java": "class Solution {\n    public List<List<String>> partition(String s) {\n        int n = s.length();\n        boolean[][] isPal = new boolean[n][n];\n        for (int i = n - 1; i >= 0; i--) {\n            for (int j = i; j < n; j++) {\n                if (s.charAt(i) == s.charAt(j) && (j - i <= 2 || isPal[i + 1][j - 1])) {\n                    isPal[i][j] = true;\n                }\n            }\n        }\n\n        List<List<String>> res = new ArrayList<>();\n        List<String> path = new ArrayList<>();\n        dfs(s, 0, isPal, path, res);\n        return res;\n    }\n\n    private void dfs(String s, int start, boolean[][] isPal,\n                     List<String> path, List<List<String>> res) {\n        if (start == s.length()) {\n            res.add(new ArrayList<>(path));\n            return;\n        }\n        for (int end = start; end < s.length(); end++) {\n            if (isPal[start][end]) {\n                path.add(s.substring(start, end + 1));\n                dfs(s, end + 1, isPal, path, res);\n                path.remove(path.size() - 1);\n            }\n        }\n    }\n}",
        "c": "static void dfs(const char* s, int n, int start, bool isPal[16][16],\n                int pathStart[16], int pathEnd[16], int pathLen,\n                char**** res, int* returnSize, int** colSizes, int* cap) {\n    if (start == n) {\n        if (*returnSize == *cap) {\n            *cap *= 2;\n            *res = (char***)realloc(*res, (*cap) * sizeof(char**));\n            *colSizes = (int*)realloc(*colSizes, (*cap) * sizeof(int));\n        }\n        char** group = (char**)malloc(pathLen * sizeof(char*));\n        for (int k = 0; k < pathLen; k++) {\n            int subLen = pathEnd[k] - pathStart[k] + 1;\n            group[k] = (char*)malloc((subLen + 1) * sizeof(char));\n            memcpy(group[k], s + pathStart[k], subLen);\n            group[k][subLen] = '\\0';\n        }\n        (*colSizes)[*returnSize] = pathLen;\n        (*res)[(*returnSize)++] = group;\n        return;\n    }\n    for (int end = start; end < n; end++) {\n        if (isPal[start][end]) {\n            pathStart[pathLen] = start;\n            pathEnd[pathLen] = end;\n            dfs(s, n, end + 1, isPal, pathStart, pathEnd, pathLen + 1,\n                res, returnSize, colSizes, cap);\n        }\n    }\n}\n\nchar*** partition(char* s, int* returnSize, int** returnColumnSizes) {\n    int n = strlen(s);\n    bool isPal[16][16] = {false};  // 题目限定 s 长度 <= 16\n    for (int i = n - 1; i >= 0; i--) {\n        for (int j = i; j < n; j++) {\n            if (s[i] == s[j] && (j - i <= 2 || isPal[i + 1][j - 1])) {\n                isPal[i][j] = true;\n            }\n        }\n    }\n\n    int cap = 256;\n    char*** res = (char***)malloc(cap * sizeof(char**));\n    *returnColumnSizes = (int*)malloc(cap * sizeof(int));\n    *returnSize = 0;\n\n    int pathStart[16], pathEnd[16];\n    dfs(s, n, 0, isPal, pathStart, pathEnd, 0, &res, returnSize, returnColumnSizes, &cap);\n    return res;\n}"
