        "python": "class Solution:\n    def isValid(self, s: str) -> bool:\n        # 奇数长度的字符串绝不可能两两配对成功，提前 O(1) 剪枝\n        if len(s) % 2 == 1:\n            return False\n\n        mp = {'(': ')', '[': ']', '{': '}'}\n        st = []\n        for ch in s:\n            if ch in mp:\n                # 巧思：遇到左括号时，直接压入它期待匹配的右括号！\n                st.append(mp[ch])\n            else:\n                # 遇到右括号：若栈已空或栈顶期待的右括号与当前字符不符，立即失配\n                if not st or st.pop() != ch:\n                    return False\n\n        # 最终必须栈空才算全部配对完毕\n        return not st",
        "cpp": "class Solution {\npublic:\n    bool isValid(string s) {\n        if (s.size() % 2 == 1) return false;\n\n        string st;  // 直接用 string 充当字符栈，连续内存且极度轻量\n        for (char ch : s) {\n            if (ch == '(') {\n                st.push_back(')');\n            } else if (ch == '[') {\n                st.push_back(']');\n            } else if (ch == '{') {\n                st.push_back('}');\n            } else {\n                if (st.empty() || st.back() != ch) {\n                    return false;\n                }\n                st.pop_back();\n            }\n        }\n        return st.empty();\n    }\n};",
        "java": "class Solution {\n    public boolean isValid(String s) {\n        int n = s.length();\n        if (n % 2 == 1) return false;\n\n        // 用原生 char[] 模拟栈，避免 Deque<Character> 高频自动装箱拆箱开销\n        char[] st = new char[n];\n        int top = 0;\n        for (int i = 0; i < n; i++) {\n            char ch = s.charAt(i);\n            if (ch == '(') {\n                st[top++] = ')';\n            } else if (ch == '[') {\n                st[top++] = ']';\n            } else if (ch == '{') {\n                st[top++] = '}';\n            } else {\n                if (top == 0 || st[--top] != ch) {\n                    return false;\n                }\n            }\n        }\n        return top == 0;\n    }\n}",
