      "isTop20": true,
      "codes": {
        "python": "class Solution:\n    def decodeString(self, s: str) -> str:\n        st = []      # 栈中保存进入 '[' 之前的现场元组: (外层已拼前缀, 当前括号重复倍数)\n        res = \"\"     # 当前层正在拼接的字符串\n        multi = 0    # 当前累积解析的重复倍数\n\n        for ch in s:\n            if ch.isdigit():\n                # 倍数可能是多位数（如 100[a]），必须乘 10 累加！\n                multi = multi * 10 + int(ch)\n            elif ch == '[':\n                # 封存外层现场入栈，并重置当前层状态开始收集括号内子串\n                st.append((res, multi))\n                res, multi = \"\", 0\n            elif ch == ']':\n                # 当前括号结束，弹出最近一层外层前缀与倍数完成展开组装\n                last_res, cur_multi = st.pop()\n                res = last_res + cur_multi * res\n            else:\n                res += ch\n\n        return res",
        "cpp": "class Solution {\npublic:\n    string decodeString(string s) {\n        stack<pair<string, int>> st;\n        string res;\n        int multi = 0;\n\n        for (char ch : s) {\n            if (isdigit(static_cast<unsigned char>(ch))) {\n                multi = multi * 10 + (ch - '0');\n            } else if (ch == '[') {\n                st.emplace(std::move(res), multi);\n                res.clear();\n                multi = 0;\n            } else if (ch == ']') {\n                auto [lastRes, curMulti] = std::move(st.top());\n                st.pop();\n                string expanded = std::move(lastRes);\n                expanded.reserve(expanded.size() + res.size() * curMulti);\n                for (int k = 0; k < curMulti; ++k) {\n                    expanded += res;\n                }\n                res = std::move(expanded);\n            } else {\n                res.push_back(ch);\n            }\n        }\n        return res;\n    }\n};",
        "java": "class Solution {\n    public String decodeString(String s) {\n        Deque<StringBuilder> strSt = new ArrayDeque<>();\n        Deque<Integer> numSt = new ArrayDeque<>();\n        StringBuilder res = new StringBuilder();\n        int multi = 0;\n\n        for (int i = 0; i < s.length(); i++) {\n            char ch = s.charAt(i);\n            if (ch >= '0' && ch <= '9') {\n                multi = multi * 10 + (ch - '0');\n            } else if (ch == '[') {\n                strSt.push(res);\n                numSt.push(multi);\n                res = new StringBuilder();  // 必须新建实例，不能 clear 原引用！\n                multi = 0;\n            } else if (ch == ']') {\n                StringBuilder lastRes = strSt.pop();\n                int curMulti = numSt.pop();\n                for (int k = 0; k < curMulti; k++) {\n                    lastRes.append(res);\n                }\n                res = lastRes;\n            } else {\n                res.append(ch);\n            }\n        }\n        return res.toString();\n    }\n}",
        "c": "typedef struct {\n    char* str;\n    int len;\n    int multi;\n} Frame;\n\nstatic void appendBytes(char** buf, int* len, int* cap, const char* src, int srcLen) {\n    if (*len + srcLen + 1 > *cap) {\n        while (*len + srcLen + 1 > *cap) *cap *= 2;\n        *buf = (char*)realloc(*buf, (*cap) * sizeof(char));\n    }\n    memcpy(*buf + *len, src, srcLen);\n    *len += srcLen;\n    (*buf)[*len] = '\\0';\n}\n\nchar* decodeString(char* s) {\n    Frame st[32];  // 括号嵌套深度不超过 30\n    int top = 0;\n\n    int cap = 64, len = 0;\n    char* res = (char*)malloc(cap * sizeof(char));\n    res[0] = '\\0';\n    int multi = 0;\n\n    for (int i = 0; s[i] != '\\0'; i++) {\n        char ch = s[i];\n        if (ch >= '0' && ch <= '9') {\n            multi = multi * 10 + (ch - '0');\n        } else if (ch == '[') {\n            st[top++] = (Frame){res, len, multi};\n            cap = 64;\n            len = 0;\n            res = (char*)malloc(cap * sizeof(char));\n            res[0] = '\\0';\n            multi = 0;\n        } else if (ch == ']') {\n            Frame f = st[--top];\n            int prevCap = f.len + len * f.multi + 16;\n            f.str = (char*)realloc(f.str, prevCap * sizeof(char));\n            for (int k = 0; k < f.multi; k++) {\n                memcpy(f.str + f.len, res, len);\n                f.len += len;\n            }\n            f.str[f.len] = '\\0';\n            free(res);\n            res = f.str;\n            len = f.len;\n            cap = prevCap;\n        } else {\n            appendBytes(&res, &len, &cap, &ch, 1);\n        }\n    }\n    return res;\n}"
      },
