        "java": "class Solution {\n    public int largestRectangleArea(int[] heights) {\n        int n = heights.length;\n        int[] h = new int[n + 2];\n        System.arraycopy(heights, 0, h, 1, n);  // h[0] 和 h[n + 1] 天然为哨兵 0\n\n        int[] st = new int[n + 2];\n        int top = 0;\n        int ans = 0;\n\n        for (int i = 0; i < n + 2; i++) {\n            while (top > 0 && h[i] < h[st[top - 1]]) {\n                int curH = h[st[--top]];\n                int width = i - st[top - 1] - 1;\n                ans = Math.max(ans, curH * width);\n            }\n            st[top++] = i;\n        }\n        return ans;\n    }\n}",
        "c": "int largestRectangleArea(int* heights, int heightsSize) {\n    int m = heightsSize + 2;\n    int* h = (int*)calloc(m, sizeof(int));\n    memcpy(h + 1, heights, heightsSize * sizeof(int));\n\n    int* st = (int*)malloc(m * sizeof(int));\n    int top = 0;\n    int ans = 0;\n\n    for (int i = 0; i < m; i++) {\n        while (top > 0 && h[i] < h[st[top - 1]]) {\n            int curH = h[st[--top]];\n            int width = i - st[top - 1] - 1;\n            int area = curH * width;\n            if (area > ans) {\n                ans = area;\n            }\n        }\n        st[top++] = i;\n    }\n\n    free(h);\n    free(st);\n    return ans;\n}"
