        "java": "class Solution {\n    public int minDistance(String word1, String word2) {\n        int m = word1.length(), n = word2.length();\n        int[][] dp = new int[m + 1][n + 1];\n\n        for (int i = 1; i <= m; i++) dp[i][0] = i;\n        for (int j = 1; j <= n; j++) dp[0][j] = j;\n\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = Math.min(\n                        dp[i - 1][j - 1],\n                        Math.min(dp[i - 1][j], dp[i][j - 1])\n                    ) + 1;\n                }\n            }\n        }\n        return dp[m][n];\n    }\n}",
        "c": "static inline int min3(int a, int b, int c) {\n    int t = a < b ? a : b;\n    return t < c ? t : c;\n}\n\nint minDistance(char* word1, char* word2) {\n    int m = (int)strlen(word1);\n    int n = (int)strlen(word2);\n    int cols = n + 1;\n    int* dp = (int*)malloc(sizeof(int) * (m + 1) * cols);\n\n    dp[0] = 0;\n    for (int i = 1; i <= m; i++) dp[i * cols] = i;\n    for (int j = 1; j <= n; j++) dp[j] = j;\n\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (word1[i - 1] == word2[j - 1]) {\n                dp[i * cols + j] = dp[(i - 1) * cols + (j - 1)];\n            } else {\n                dp[i * cols + j] = min3(\n                    dp[(i - 1) * cols + j],       // 删除\n                    dp[i * cols + (j - 1)],       // 插入\n                    dp[(i - 1) * cols + (j - 1)]  // 替换\n                ) + 1;\n            }\n        }\n    }\n    int ans = dp[m * cols + n];\n    free(dp);\n    return ans;\n}"
